const j = $input.item.json;
const cyrb53 = (str, seed = 0) => {
  let h1 = 0xdeadbeef ^ seed, h2 = 0x41c6ce57 ^ seed;
  for (let i = 0, ch; i < str.length; i++) {
    ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return 4294967296 * (2097151 & h2) + (h1 >>> 0);
};
let out;
if (j.body !== undefined && j.headers !== undefined) {
  // Web portal (Webhook)
  const b = j.body || {};
  out = {
    channel: 'web', chat_id: null, raw: 'web:' + String(b.student_id || 'anonymous'),
    student_name: b.name || '', text: String(b.message || '').trim(),
    callback_data: String(b.callback_data || ''), email: b.email || '', callback_query_id: null
  };
} else if (j.callback_query) {
  const cq = j.callback_query;
  out = {
    channel: 'telegram', chat_id: cq.message.chat.id, raw: 'tg:' + cq.from.id,
    student_name: cq.from.first_name || '', text: '', callback_data: cq.data || '',
    email: '', callback_query_id: cq.id
  };
} else {
  const m = j.message || j.edited_message || {};
  out = {
    channel: 'telegram', chat_id: m.chat ? m.chat.id : null,
    raw: 'tg:' + (m.from ? m.from.id : (m.chat ? m.chat.id : 'unknown')),
    student_name: (m.from && m.from.first_name) || '', text: String(m.text || '').trim(),
    callback_data: '', email: '', callback_query_id: null
  };
}
// Pseudonymised numeric id (FERPA/COPPA): the raw Telegram id is never stored.
out.student_id = cyrb53(out.raw, 7);
delete out.raw;
return { json: out };

const n = $('Config').first().json;
const res = $input.item.json || {};
const stored = (res.result && res.result.payload) ? res.result.payload : null;
const profile = Object.assign({
  student_id: n.student_id, name: '', email: '', level: 2, bank: 'ALL', mode: 'chat',
  streak: 0, attempt: 1, current_qid: null, current_options: [], current_tier: null, seen: [],
  set_answered: 0, set_correct: 0, total_answered: 0, total_correct: 0,
  mastery: {}, jre_history: [], created_at: new Date().toISOString()
}, stored || {});
if (n.email) profile.email = n.email;
if (!profile.name && n.student_name) profile.name = n.student_name;
return { json: { ...n, profile, is_new: !stored } };

// WINGS OF ISIS - safety, integrity and scope guardrail + intent router
const d = $input.item.json;
const text = (d.text || '').trim();
const cb = d.callback_data || '';
const words = text.split(/\s+/).filter(Boolean).length;

const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const distress = /(kill myself|suicid|end my life|want to die|self[- ]?harm|hurt myself|no reason to live|انتحر|اقتل نفسي|عايز اموت|عاوز اموت|أريد أن أموت|مش عايز اعيش)/i;
const cheating = /(write (my|the|an?) (whole )?(essay|paragraph|homework)|do my homework|give me (all )?the answers?|just tell me the answer|answer key|اكتبلي|اكتب لي|حل لي الواجب)/i;
const offTopic = /(python|javascript|write (some )?code|bitcoin|football score|who won the|minecraft|fortnite|election|dating|celebrity gossip)/i;

// Included guidebook, guide, and Arabic aliases to ensure they are captured as commands
const greetingOrMenu = /^(hi+|hello+|hey+|start|help|menu|stop|exit|guidebook|guide|doleel|دليل|good (morning|afternoon|evening)|welcome|salam|اهلا|أهلا|مرحبا|السلام عليكم|ازيك|صباح الخير|مساء الخير|ابدا|ابدأ|القائمة|رجوع|توقف)$/i;

let route = 'socratic', block_reason = '';
if (distress.test(text)) route = 'distress';
else if (cheating.test(text)) { route = 'blocked'; block_reason = 'cheating'; }
else if (offTopic.test(text) && words < 30) { route = 'blocked'; block_reason = 'offtopic'; }
else if (emailPattern.test(text)) route = 'command';
else if (cb) route = (cb.startsWith('ans:') || cb === 'next') ? 'quiz' : 'command';
else if (text.startsWith('/')) route = text.toLowerCase().startsWith('/quiz') ? 'quiz' : 'command';
else if (greetingOrMenu.test(text)) route = 'command';
else if (d.profile.mode === 'essay_builder') route = 'socratic'; // Routes directly to Gemini!

return { json: { ...d, route, block_reason, words } };

const d = $input.item.json;
const reply = `💛 I'm really glad you told me. What you are feeling matters more than any lesson, and you do not have to carry it alone.

Please talk to someone you trust right now - a parent, a family member or your school counsellor. ${d.helpline_text}

We will pause the English practice. When you feel ready, I am here.`;
return { json: { ...d, reply_text: reply, keyboard_type: 'text', options: [], qid: null,
  profile: d.profile, email_payload: null, memory_item: null } };

const d = $input.item.json;
const kb = d.keyboard_type || 'text';
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const out = { ...d };
out.profile = { ...d.profile, updated_at: new Date().toISOString() };
out.student_key = 'S' + d.student_id;

// 1. Convert Markdown bold and links to Telegram HTML
let text = esc(d.reply_text)
  .replace(/\*\*(.+?)\*\*/g, '<b>$1</b>')
  .replace(/\[(.+?)\]\((https?:\/\/[^\s)]+)\)/g, '<a href="$2"><b>$1</b></a>');

// 2. Attach the Supabase Card Image for Vocabulary (V1 questions)
const SUPABASE_BASE_URL = "https://jubfxtevvdzjbimputjw.supabase.co/storage/v1/object/public/kemet-assets/vocab/";

if (d.qid && d.qid.startsWith('V1')) {
  const imageUrl = `${SUPABASE_BASE_URL}${d.qid}.png`;
  text = `<a href="${imageUrl}">&#8205;</a>` + text;
}

out.tg_text = text;
['a', 'b', 'c', 'd'].forEach((l, i) => { out['cb_' + l] = d.qid ? `ans:${d.qid}:${i}` : 'next'; });
out.cb_next = 'next';
out.route_key = d.channel === 'web' ? 'web' : 'tg_' + kb;
out.web_response = {
  reply: d.reply_text, 
  keyboard: kb, 
  options: d.options || [], 
  question_id: d.qid || null,
  level: out.profile.level, 
  streak: out.profile.streak,
  progress: { answered: out.profile.total_answered, correct: out.profile.total_correct }
};

return { json: out };

const d = $input.item.json;
let reply = '';

if (d.block_reason === 'cheating') {
  reply = `🪽 Wings of Isis: I can't write your answers or essay for you - but I can walk beside you until YOU can.\n\nLet's start small (Justification): what is your position on the question, in one sentence? Or tap /quiz for adaptive practice.`;
} else if (d.block_reason === 'too_short') {
  reply = `🪽 Your writing is a bit too short for me to properly evaluate on the 4-dimension JRE+ rubric! Please expand your thoughts and aim for at least 150 words.\n\nOr tap /menu to return to the Main Menu.`;
} else {
  reply = `🪽 Wings of Isis: I'm Kemet, your Unit 1 English tutor (Living Well in a Complex World + The Lost World, Chapter 1), so I'll stay within that map.\n\nTry /quiz for practice, /essay for JRE+ feedback, or ask me about Unit 1 grammar, vocabulary or readings.`;
}

return { json: { ...d, reply_text: reply, keyboard_type: 'text', options: [], qid: null, profile: d.profile, email_payload: null, memory_item: null } };

const d = $input.item.json;
const p = d.profile;
const cb = d.callback_data || '';
let mode = 'serve', qid = null, selected = null;
if (cb.startsWith('ans:')) {
  const parts = cb.split(':');
  qid = parts[1]; selected = parseInt(parts[2], 10);
  if (p.current_qid && qid === p.current_qid) mode = 'check';   // stale buttons just serve a new question
}
let body;
if (mode === 'check') {
  body = { filter: { must: [{ key: 'metadata.id', match: { value: qid } }] }, limit: 1, with_payload: true, with_vector: false };
} else {
  const must = [
    { key: 'metadata.tier', match: { value: 'T' + p.level } },
    { key: 'metadata.format', match: { value: 'mcq' } }
  ];
  if (p.bank && p.bank !== 'ALL' && p.level > 0) must.push({ key: 'metadata.bank', match: { value: p.bank } });
  const filter = { must };
  if ((p.seen || []).length) filter.must_not = [{ key: 'metadata.id', match: { any: p.seen } }];
  body = { filter, limit: 60, with_payload: true, with_vector: false };
}
return { json: { ...d, quiz_mode: mode, qid, selected, qdrant_body: body } };

// ADAPTIVE ENGINE: Observe -> Decide -> Act (Backtick-free + Skill Names + /menu footer)
const pl = $('Quiz Planner').first().json;
const res = $input.item.json || {};
const p = JSON.parse(JSON.stringify(pl.profile));
p.mastery = p.mastery || {};

const FALLBACK_BANK = [
  { id: "D1-01", bank: "D1", tier: 0, prompt: "Choose the correct word: The teacher ___ helps me is kind.", options: ["who", "which"], answer: "who", why: "Use 'who' for a person doing the action in a relative clause." },
  { id: "D1-02", bank: "D1", tier: 0, prompt: "Choose the correct word: The book ___ I borrowed is on the desk.", options: ["who", "which"], answer: "which", why: "Use 'which' for things in a relative clause." },
  { id: "D1-06", bank: "D1", tier: 0, prompt: "Choose the correct word: The boy ___ football is my brother.", options: ["playing", "played"], answer: "playing", why: "The boy performs the action, so we use the active -ing form." },
  { id: "D1-08", bank: "D1", tier: 0, prompt: "Choose the correct word: ___ tired, Ali sat down to rest.", options: ["Feeling", "Felt"], answer: "Feeling", why: "Ali is the person experiencing the feeling, so use the active -ing participle." },
  { id: "D1-12", bank: "D1", tier: 0, prompt: "Choose the correct word: If I were you, I ___ ask the teacher.", options: ["will", "would"], answer: "would", why: "Second-conditional advice ('If I were you') takes 'would' + base verb." },

  { id: "V1-01", bank: "V1", tier: 1, prompt: "A period of ten years is called a ___.", options: ["survey", "decade", "platform", "symptom"], answer: "decade", why: "A decade refers to a period of ten years." },
  { id: "V1-07", bank: "V1", tier: 1, prompt: "A ___ lifestyle involves spending too much time sitting and using screens.", options: ["active", "balanced", "physical", "sedentary"], answer: "sedentary", why: "An inactive routine with very little movement is defined as sedentary." },
  { id: "R1-03", bank: "R1", tier: 1, prompt: "I know a student ___ brother works as a school counselor.", options: ["who", "whom", "which", "whose"], answer: "whose", why: "Use the possessive relative pronoun 'whose' directly before a noun." },
  { id: "P1-03", bank: "P1", tier: 1, prompt: "Which sentence is grammatically correct?", options: ["The article which I read was useful.", "The article which I read it was useful.", "The article which read I was useful.", "The article I which read was useful."], answer: "The article which I read was useful.", why: "The relative pronoun already replaces the object, so repeating 'it' is incorrect." },
  { id: "C1-06", bank: "C1", tier: 1, prompt: "If I ___ you, I would check the source of that health claim.", options: ["were", "am", "will be", "had been"], answer: "were", why: "Formal second-conditional advice uses 'If I were you'." },

  { id: "V1-11", bank: "V1", tier: 2, prompt: "According to Bandura, a person's belief in their ability to succeed and change habits is called ___.", options: ["self-esteem", "social comparison", "dissatisfaction", "self-efficacy"], answer: "self-efficacy", why: "Bandura defines belief in one's own capability to execute actions as self-efficacy." },
  { id: "R1-15", bank: "R1", tier: 2, prompt: "Choose the sentence that avoids a repeated object pronoun error:", options: ["The study I read it yesterday was clear.", "The study who I read was clear.", "The study where I read was clear.", "The study I read yesterday was clear."], answer: "The study I read yesterday was clear.", why: "In a relative clause, do not repeat the object pronoun ('it') after the verb." },
  { id: "P1-14", bank: "P1", tier: 2, prompt: "Which sentence avoids a dangling participle?", options: ["Walking to school, the rain began.", "Walking to school, I felt the rain begin.", "Walking to school, the umbrella was forgotten.", "Having walked to school, the rain started."], answer: "Walking to school, I felt the rain begin.", why: "The person doing the walking must appear as the main subject immediately after the comma." },
  { id: "C2-15", bank: "C2", tier: 2, prompt: "Which is a correct formal inversion of: 'If I were you, I would rest'?", options: ["Were I you, I would rest.", "Was I you, I would rest.", "Did I were you, I would rest.", "If were I you, I would rest."], answer: "Were I you, I would rest.", why: "In a second-conditional inversion, 'if' is dropped and 'Were' moves before the subject." },
  { id: "C1-17", bank: "C1", tier: 2, prompt: "Schools can improve student well-being ___ families and communities also share responsibility.", options: ["in case of", "provided that", "without", "despite"], answer: "provided that", why: "To introduce a required condition followed by a full subject-verb clause, use 'provided that'." },
  { id: "N1-12", bank: "N1", tier: 2, prompt: "In Chapter 1 of The Lost World, why does Edward Malone ask Mr. McArdle for a dangerous assignment?", options: ["He wants higher pay.", "Gladys Hungerton said she admires a brave man of action.", "Professor Challenger invited him.", "He wants to leave journalism."], answer: "Gladys Hungerton said she admires a brave man of action.", why: "Malone seeks danger to win the admiration of Gladys Hungerton." },

  { id: "V1-21", bank: "V1", tier: 3, prompt: "A local park is unsafe and healthy food is unaffordable. Under the WHO framework, these are examples of ___.", options: ["personal choice", "structural barriers", "internal locus of control", "self-efficacy"], answer: "structural barriers", why: "Obstacles built into the social or physical environment that limit choice are structural barriers." },
  { id: "V1-22", bank: "V1", tier: 3, prompt: "A school cafeteria places fresh fruit at eye level but leaves all other food options available. According to Thaler, this is a ___.", options: ["nudge", "ban", "compulsion", "punishment"], answer: "nudge", why: "Reshaping the choice architecture to make healthy options easier without restricting freedom is a nudge." },
  { id: "R1-24", bank: "R1", tier: 3, prompt: "A study shows teens using image-based social media over 3 hours daily are twice as likely to report low self-esteem. Which conclusion is best supported?", options: ["Social media directly causes low self-esteem.", "There is an association, but causation is not proven.", "All teens feel bad on social media.", "Social media has zero effect."], answer: "There is an association, but causation is not proven.", why: "'Twice as likely to report' demonstrates statistical correlation/association, not proven causation." },
  { id: "S1-26", bank: "S1", tier: 3, prompt: "Which sentence uses a correct third-conditional inversion?", options: ["Had I slept earlier, I would have focused better.", "If I sleep earlier, I will focus better.", "Should I sleep earlier, I focus better.", "Were I sleeping earlier, I would have focused."], answer: "Had I slept earlier, I would have focused better.", why: "Third-conditional inversion drops 'if' and places 'Had' + subject + past participle at the start." },
  { id: "C1-21", bank: "C1", tier: 3, prompt: "___ you experience high exam stress, speaking to a family member or counselor can help.", options: ["Had", "Should", "Were", "Unless"], answer: "Should", why: "Formal first-conditional inversion uses 'Should' + subject + base verb." }
];

const SKILL_LABELS = {
  D1: 'Diagnostic Support',
  V1: 'Core Vocabulary',
  V2: 'Academic Vocabulary',
  R1: 'Relative Clauses',
  R2: 'Advanced Relative Clauses',
  P1: 'Participle Clauses',
  C1: 'Conditionals & Hedging',
  C2: 'Conditional Inversions',
  S1: 'Sentence Synthesis',
  L1: 'Reading & Listening',
  N1: 'The Lost World (Ch. 1)'
};

const toQ = function(pt) {
  if (pt.prompt && Array.isArray(pt.options)) return pt;
  const m = (pt.payload && pt.payload.metadata) || {};
  return {
    id: m.id, bank: m.bank, tier: Number(String(m.tier || 'T2').replace('T', '')), prompt: m.prompt,
    options: String(m.options || '').split('||').filter(Boolean), answer: m.answer, why: m.why || ''
  };
};

let rawPts = (res.result && res.result.points && res.result.points.length) ? res.result.points.map(toQ) : FALLBACK_BANK;

let pts;
if (pl.quiz_mode === 'check') {
  pts = rawPts.filter(function(q) { return q.id === pl.qid; });
  if (!pts.length) pts = FALLBACK_BANK.filter(function(q) { return q.id === pl.qid; });
} else {
  pts = rawPts.filter(function(q) { return q.tier === p.level && (p.bank === 'ALL' || p.level === 0 || q.bank === p.bank) && !(p.seen || []).includes(q.id); });
  if (!pts.length) {
    pts = FALLBACK_BANK.filter(function(q) { return q.tier === p.level && (p.bank === 'ALL' || p.level === 0 || q.bank === p.bank) && !(p.seen || []).includes(q.id); });
  }
  if (!pts.length) {
    p.seen = [];
    pts = FALLBACK_BANK.filter(function(q) { return q.tier === p.level; });
  }
}

const THRESH = Number(pl.report_threshold || 70);
const SET = Number(pl.set_size || 5);
const TIERS = ['🪷 Support (D1)', '🏛️ Foundation (Tier 1)', '⚖️ Apply (Tier 2)', '👑 Challenge (Tier 3)'];

const shuffle = function(a) {
  const b = a.slice();
  for (let i = b.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const tmp = b[i]; b[i] = b[j]; b[j] = tmp;
  }
  return b;
};

const maskAnswer = function(why, ans) {
  if (!ans) return why;
  const safe = ans.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return why.replace(new RegExp(safe, 'gi'), '____');
};

const fmtQuestion = function(q, o) {
  const L = ['A', 'B', 'C', 'D'];
  const skillName = SKILL_LABELS[q.bank] || q.bank;
  return '🏺 **' + skillName + ' (' + q.id + ')** · ' + TIERS[q.tier] + '\n\n❓ ' + q.prompt + '\n\n' +
    o.map(function(x, i) { return '**' + L[i] + ')** ' + x; }).join('\n') +
    '\n\n──────────\n🏠 Tap /menu or the button below anytime to pause & return to the Main Menu.';
};

const reportHtml = function(pct) {
  return '<div style="font-family:Arial,sans-serif;max-width:580px;color:#12161F;border:1px solid #e0e0e0;border-radius:8px;padding:22px">' +
    '<h2 style="color:#167B80;margin-top:0">🏺 KEMET: The Nile Flow - Mastery Report</h2>' +
    '<p style="color:#B8860B;font-style:italic;margin-top:0">Nourishing your knowledge from the rich soil of Egypt. 🌾💧</p>' +
    '<div style="background:#f4fbfb;padding:14px;border-radius:6px;margin:16px 0;border-left:4px solid #167B80">' +
      '<p style="margin:4px 0"><b>Student:</b> ' + (p.name || 'Scholar') + '</p>' +
      '<p style="margin:4px 0"><b>Practice Set Evaluation:</b> ' + p.set_correct + '/' + p.set_answered + ' first-try correct (' + pct + '%)</p>' +
      '<p style="margin:4px 0"><b>Current Readiness Tier:</b> ' + TIERS[p.level] + '</p>' +
      '<p style="margin:4px 0;color:' + (pct < THRESH ? '#c53030' : '#22543d') + ';"><b>Feedback:</b> ' + 
        (pct < THRESH ? 'The score is below the ' + THRESH + '% mastery threshold. A brief teacher check-in is recommended (Human-in-the-Loop).' : 'Solid mastery on this set — outstanding focus!') + 
      '</p>' +
    '</div>' +
    '<p style="color:#666;font-size:12px;margin-bottom:20px">💡 Eye of Horus hints are provided before direct answers to protect productive struggle.</p>' +

    // KEMET Ecosystem Container
    '<div style="background:#fdfcf7;border:1px dashed #d1c18d;border-radius:8px;padding:20px;text-align:center;">' +
      '<h4 style="color:#167B80;margin:0 0 8px 0;font-size:16px;">🌐 Explore the Full KEMET Ecosystem</h4>' +
      '<p style="color:#4a5568;font-size:13px;line-height:1.6;margin:0 0 16px 0;">' +
        'Immerse yourself deeper in the learning experience with interactive writing labs, live mastery analytics, visual guides, and our multimedia channels:' +
      '</p>' +

      // Ecosystem Buttons
      '<div style="margin-bottom:12px;">' +
        '<a href="https://glowing-tabletop-production.weweb.io/" target="_blank" style="background:#167B80;color:#ffffff;padding:10px 18px;border-radius:20px;text-decoration:none;font-weight:bold;font-size:13px;display:inline-block;margin:4px;">' +
          '🌊 Official Platform' +
        '</a> ' +
        '<a href="https://kemet-master-ancient-egyptian-scribe-gold-design.ai.studio/" target="_blank" style="background:#0E5356;color:#ffffff;padding:10px 18px;border-radius:20px;text-decoration:none;font-weight:bold;font-size:13px;display:inline-block;margin:4px;">' +
          '📱 Mobile App' +
        '</a>' +
      '</div>' +

      '<div style="margin-bottom:4px;">' +
        '<a href="https://www.youtube.com/@KemetTheNileFlow" target="_blank" style="background:#c4302b;color:#ffffff;padding:7px 14px;border-radius:16px;text-decoration:none;font-size:12px;display:inline-block;margin:3px;">' +
          '▶️ YouTube' +
        '</a> ' +
        '<a href="https://www.instagram.com/kemethenile/" target="_blank" style="background:#E1306C;color:#ffffff;padding:7px 14px;border-radius:16px;text-decoration:none;font-size:12px;display:inline-block;margin:3px;">' +
          '📸 Instagram' +
        '</a> ' +
        '<a href="https://www.facebook.com/people/Kemet-The-Nile-Flow/61595359775648/?mibextid=wwXIfr&rdid=l45Jc2MSuGOHcDiK&share_url=https%3A%2F%2Fwww.facebook.com%2Fshare%2F1CDMaxKF8q%2F%3Fmibextid%3DwwXIfr" target="_blank" style="background:#1877F2;color:#ffffff;padding:7px 14px;border-radius:16px;text-decoration:none;font-size:12px;display:inline-block;margin:3px;">' +
          '📘 Facebook' +
        '</a>' +
      '</div>' +
    '</div>' +
    '<p style="color:#a0aec0;font-size:11px;margin-top:18px;margin-bottom:4px;text-align:center;font-style:italic;">⚠️ This is an automated notification from a no-reply address. Please do not reply directly to this email.</p>' +
    '<p style="color:#888;font-size:11px;margin-top:4px;text-align:center;">Protected by the Wings of Isis · KEMET: The Nile Flow Adaptive Socratic Tutor</p>' +
  '</div>';
};

let reply = '', kb = 'text', opts = [], qid = null, email = null, memory = null;

if (pl.quiz_mode === 'check') {
  const q = pts.length ? pts[0] : null;
  const chosen = (p.current_options || [])[pl.selected];
  if (!q || chosen === undefined) {
    p.current_qid = null; p.attempt = 1;
    reply = '🪔 Let us load a fresh question for you! Tap **Next question ▶** below (or tap /menu for the Main Menu).';
    kb = 'next';
  } else {
    const bank = q.bank;
    p.mastery[bank] = p.mastery[bank] || { a: 0, c: 0 };
    const correct = chosen === q.answer;
    let resolved = false;
    if (correct) {
      resolved = true;
      if (p.attempt === 1) {
        p.streak = (p.streak || 0) + 1; p.set_correct++; p.total_correct++; p.mastery[bank].c++;
        reply = '✅☀️ **Correct on the first try! Shining like KEMET gold!**\n💡 ' + q.why;
        if (p.streak >= 2 && p.level < 3) {
          p.level++; p.streak = 0;
          reply += '\n\n🔼👑 **Two in a row! Moving you UP to ' + TIERS[p.level] + ' on the wings of Isis! 🪽**';
        } else if (p.streak >= 2) {
          reply += '\n\n🌟 **Challenge-tier streak: ' + p.streak + '!**';
        } else {
          reply += '\n\n🔥 **Active Streak:** ' + p.streak;
        }
      } else {
        p.streak = 0;
        reply = '✅🗝️ **You worked it out yourself!**\n💡 ' + q.why + '\n\nLike scholars decoding the Rosetta Stone, you unlocked this! 📜';
      }
      kb = 'next';
    } else if (p.attempt === 1) {
      p.attempt = 2;
      opts = p.current_options; qid = q.id;
      kb = opts.length === 2 ? 'mcq2' : 'mcq4';
      reply = '👁️ **Eye of Horus Hint (For clarity and protection):**\n' + maskAnswer(q.why, q.answer) +
        '\n\n🛡️ I will not give away the answer yet! Look closely at the hint above and try one more time:\n\n' + fmtQuestion(q, opts);
    } else {
      resolved = true; p.streak = 0;
      reply = '📘🤝 **Let us work it out together (Gradual Release):**\nThe correct answer is **' + q.answer + '**.\n💡 ' + q.why;
      if (p.level > 0) {
        p.level--;
        reply += '\n\n🔽🪷 **Let us rebuild confidence at ' + TIERS[p.level] + ' with scaffolded choices.**';
      }
      memory = {
        type: 'misconception', skill: bank, qid: q.id,
        text: 'Misconception on ' + q.id + ' (' + bank + ', ' + TIERS[q.tier] + '): student chose "' + chosen + '" instead of "' + q.answer + '" even after a hint. Item: ' + q.prompt + ' Rationale: ' + q.why
      };
      kb = 'next';
    }
    if (resolved) {
      p.total_answered++; p.set_answered++; p.mastery[bank].a++; p.attempt = 1; p.current_qid = null;
      reply += '\n\n📊 **Set Progress:** ' + p.set_answered + '/' + SET + '\n🏠 Tap /menu anytime to return to the Main Menu.';
      if (p.set_answered >= SET) {
        const pct = Math.round(100 * p.set_correct / p.set_answered);
        const to = p.email || ''; const teacher = pl.teacher_email || '';
        if (to || (pct < THRESH && teacher)) {
          email = {
            to: to || teacher, cc: (to && pct < THRESH) ? teacher : '',
            subject: 'KEMET Mastery Report - ' + pct + '%' + (pct < THRESH ? ' (needs support)' : ''),
            html: reportHtml(pct)
          };
        }
        const notified = email && (email.to === teacher || email.cc === teacher) && teacher;
        reply += '\n\n🏆 **5-Question Set Complete: ' + pct + '%!** ' +
          (pct < THRESH ? 'Let us keep practising' + (notified ? ' (a summary has been sent to your teacher).' : '.') : 'Outstanding mastery!') +
          '\n\n🔄 **Ready to switch topics?** Tap /topic or /reset to refresh my memory and start a new Study Sprint!';
        p.set_answered = 0; p.set_correct = 0;
      }
    }
  }
} else {
  const q = pts[Math.floor(Math.random() * pts.length)];
  let o = shuffle(q.options);
  if ((o.length !== 4 && o.length > 2) || (q.tier <= 1 && o.length > 2)) {
    const wrong = shuffle(o.filter(function(x) { return x !== q.answer; }));
    o = shuffle([q.answer, wrong[0]]);
  }
  p.current_qid = q.id; p.current_options = o; p.current_tier = q.tier; p.attempt = 1;
  p.seen = (p.seen || []).concat([q.id]).slice(-500);
  kb = o.length === 2 ? 'mcq2' : 'mcq4'; opts = o; qid = q.id;
  reply = fmtQuestion(q, o);
}

return { json: { ...pl, reply_text: reply, keyboard_type: kb, options: opts, qid, profile: p, email_payload: email, memory_item: memory } };

